IF i_enable THEN
	P_num:=F_num+T_num;

	IF P_num<=0 THEN
	    out_bool:=FALSE;
	ELSE
	    run_num:=run_num+1;
	    out_bool:=(run_num>F_num);
	END_IF

	IF run_num>=P_num THEN
	   	 run_num:=0;
	END_IF

ELSE 
	out_bool:=FALSE;	
	run_num:=0;
END_IF

// ===================================================================
// TCP INPUT_REGISTER 地址布局 (PLC → PC, V5.0)
// ===================================================================
// 设计原则:
//   - 每节内字段从基址连续紧排, 节尾留大块预留
//   - 节边界对齐 32W 倍数, 便于上位机分块读取
//   - 字段一旦发布不再挪位; 新字段从节末预留区追加
//   - [E] 指令回读区与 PC→PLC 区 [C][D][E] 一一对应, 让 HMI 验证收发一致
// ===================================================================
// [A] 系统状态     0   – 31    (32 W; 10 字段 = 20 W, 余 12 W)
// [B] 油路实时    32   – 95    (64 W; 11 字段 = 22 W, 余 42 W)
// [C] 控制器分量  96   – 127   (32 W;  4 字段 =  8 W, 余 24 W)
// [D] 液压站实时 128  – 159    (32 W;  6 字段 = 12 W, 余 20 W)
// [E] 指令回读   160  – 223    (64 W; 25 字段 = 50 W, 余 14 W)
// [F] 系统诊断   224  – 255    (32 W;  4 字段 =  8 W, 余 24 W)
// [G] 设备状态   256  – 319    (64 W; 由 PRG_DeviceControl 填充)
// [Z] 未来扩展   320  – 1999
// ===================================================================


// ===== [A] 系统状态 (0-31) =====
j := 0;

Float_to_TwoWord(input := GVL_PulsePressure.PP_FrameCounter_PLC);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 0-1: PLC 帧计数器 (心跳)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_SysState);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 2-3: 系统状态 0=空闲 1=冲洗 3=运行 4=停止 5=故障 (无 2)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_AlarmFlags);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 4-5: 报警标志
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_TotalCyclesDone);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 6-7: 累计循环次数
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_SysCommand);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 8-9: 系统命令回读
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Enable);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 10-11: 使能回读
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_IO_InputBits);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 12-13: 数字量输入
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_IO_OutputBits_FB);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 14-15: 数字量输出回读
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_FlushTimeRemaining);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 16-17: 冲洗排气剩余时间 (s)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_StateReady);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 18-19: 状态推进就绪标志
j := j + 2;

// 20-31: 保留 (6 字段)


// ===== [B] 油路实时 (32-95) =====
j := 32;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ActualPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 32-33: 油路实际压力 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_SetpointPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 34-35: 油路给定压力 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PressureError);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 36-37: 油路压力偏差 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ControlOutput);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 38-39: 阀控总输出 (V) = PID
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ValveCurrent);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 40-41: 比例阀电流 (mA)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_CyclesDone);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 42-43: 完成循环次数
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_Frequency_FB);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 44-45: 实际频率 (Hz)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_WavePhase);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 46-47: 波形相位 (°)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PeakPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 48-49: 本次脉冲峰值 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_TargetUpper);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 50-51: ARP1383C 上包络 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_TargetLower);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 52-53: ARP1383C 下包络 (MPa)
j := j + 2;

// 54-95: 保留 (21 字段)


// ===== [C] 控制器分量 (96-127) =====
j := 96;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_Output);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 96-97: ILC 指令修正量 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_Iteration);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 98-99: ILC 当前迭代次数
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Output);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 100-101: PID 反馈输出 (V)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Integral);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 102-103: PID 积分项 (V)
j := j + 2;

// 104-127: 保留 (12 字段)


// ===== [D] 液压站实时 (128-159) =====
j := 128;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_Pressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 128-129: 液压站系统压力 (MPa)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_Temperature);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 130-131: 液压油温度 (°C)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_OilLevel);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 132-133: 液位 (mm)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_PumpStatus);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 134-135: 液压泵运行状态
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_FilterStatus);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 136-137: 过滤器状态
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_PumpRunTime);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 138-139: 液压泵累计运行时间 (h)
j := j + 2;

// 140-159: 保留 (10 字段)


// ===== [E] 指令回读 (160-223) =====
// 镜像 PC→PLC 区 [C][D][E], 让上位机验证收发一致
// 顺序与 PC→PLC 一致, 但布局连续 (PC→PLC 节内的预留区在回读区不复制)
j := 160;

// -- 镜像 PC→PLC [C] 油路波形 (15 字段) --
Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_WaveType);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 160-161: 波形类型 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_TargetPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 162-163: 目标峰值压力 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_MinPressure);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 164-165: 最低压力 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_Frequency);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 166-167: 频率 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_HighLimit);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 168-169: 油路高压限值 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_TargetCycles);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 170-171: 目标循环次数 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_RisePct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 172-173: 上升段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_HoldPct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 174-175: 保压段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_FallPct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 176-177: 下降段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_Overshoot);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 178-179: 过冲幅值占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_RingPct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 180-181: 过冲后稳定段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_LowDwellPct);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 182-183: 低保持段占比 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_CycleReset);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 184-185: 循环计数清零 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_EnvPctP);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 186-187: 包络压力容差 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_EnvPctT);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 188-189: 包络时间容差 (回读)
j := j + 2;

// -- 镜像 PC→PLC [D] 控制器 (6 字段) --
Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_Enable);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 190-191: ILC 使能 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_MaxIter);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 192-193: ILC 最大迭代 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_ILC_LearningRate);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 194-195: ILC 学习率 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Kp);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 196-197: PID Kp (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Ki);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 198-199: PID Ki (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Oil_PID_Kd);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 200-201: PID Kd (回读)
j := j + 2;

// -- 镜像 PC→PLC [E] 液压站 (4 字段) --
Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_HighLimit);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 202-203: 液压站高压限值 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_TempLimit);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 204-205: 液压站温度限值 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_PumpCmd);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 206-207: 液压泵启停 (回读)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_Hydro_MotorSpeed);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 208-209: 电机转速设定 (回读)
j := j + 2;

// 210-223: 保留 (7 字段; 节内可加更多回读)


// ===== [F] 系统诊断 (224-255) =====
j := 224;

Float_to_TwoWord(input := GVL_PulsePressure.PP_PLC_ScanCycle);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 224-225: PLC 扫描周期 (ms)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_TCPIP_CommCycle);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 226-227: TCP 通讯周期 (ms)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_PLC_Timestamp_Low);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 228-229: 时间戳低 32 位 (ms)
j := j + 2;

Float_to_TwoWord(input := GVL_PulsePressure.PP_PLC_Timestamp_High);
INPUT_REGISTER[j]   := Float_to_TwoWord.Word_LOW;
INPUT_REGISTER[j+1] := Float_to_TwoWord.Word_HIGH;         // 230-231: 时间戳高 32 位
j := j + 2;

// 232-255: 保留 (12 字段)


// ===== [G] 设备状态 (256-319) =====
// 该区域由 PRG_DeviceControl（待重写）填充
// 建议地址分配 (占位约定):
//   256-257 : bit-packed 泵运行/故障状态 (SMP/XH/HR1/HR2)
//   258-259 : bit-packed 过滤器状态 + 相序报警 (8.01/16.01/19.01/相序)
//   260-261 : 液压站油液温度
//   262-263 : 液压站油液液位
//   264-271 : 4 路油路压力传感器
//   272-279 : SMP 压力/转速/流量反馈
//   280-283 : HR_Pump1/Pump2 频率反馈
//   284-319 : 保留 (18 字段)


// ===== [Z] 320-1999: 未来扩展 =====

// ============================================================
// 复位 / 失能
// ============================================================
IF bReset OR NOT bEnable THEN
    rPhaseAcc := 0.0;
    rTarget := rPMin;
    rTargetPrev := rPMin;
    rTargetLast := rPMin;
    rTargetLead := rPMin;
    rTargetLeadPrev := rPMin;
    rTargetLeadLast := rPMin;
    rTargetUpper := rPMin;
    rTargetLower := rPMin;
    bNewCycle := FALSE;
    bFirstRun := TRUE;
    iIdxCounter := 0;
    RETURN;
END_IF

// 频率保护
IF rFrequency < 0.01 THEN
    rTarget := rPMin;
    rTargetPrev := rPMin;
    rTargetUpper := rPMin;
    rTargetLower := rPMin;
    RETURN;
END_IF

// 每周期采样点数
iPointsPerCycle := REAL_TO_INT(1.0 / (rFrequency * rDt));
IF iPointsPerCycle < 10 THEN
    iPointsPerCycle := 10;
END_IF

// 保存上一步值
rTargetPrev := rTargetLast;

// 相位推进 (使用累加器避免长时间漂移)
rPhaseAcc := rPhaseAcc + rFrequency * rDt;
IF rPhaseAcc >= 1.0 THEN
    rPhaseAcc := rPhaseAcc - 1.0;
    bNewCycle := TRUE;
    iIdxCounter := 0;
ELSE
    bNewCycle := FALSE;
END_IF

rPhase := rPhaseAcc;
iPointIndex := iIdxCounter;


// ============================================================
// 段宽参数归一化 (每周期算一次即可，每步算无害)
// ============================================================
CASE iWaveType OF

1:  // 梯形：4 段 (rR + rH + rF + rL = 1)
    rR := rRisePct;
    rH := rHoldPct;
    rF := rFallPct;
    IF rR < 0.01 THEN rR := 0.1; END_IF
    IF rH < 0.01 THEN rH := 0.3; END_IF
    IF rF < 0.01 THEN rF := 0.1; END_IF
    rL := 1.0 - rR - rH - rF;
    IF rL < 0.0 THEN rL := 0.0; END_IF
    // 梯形不用 rRing/rPeakOS，置零以防函数访问无效值
    rRing := 0.0;
    rPeakOS := rPMax;

2:  // 水锤：5 段相对权重，强制 sum = 1
    rR := rRisePct;
    rRing := rRingPct;
    rH := rHoldPct;
    rF := rFallPct;
    rLow := rLowDwellPct;
    IF rR < 0.01 THEN rR := 0.05; END_IF
    IF rRing < 0.01 THEN rRing := 0.07; END_IF
    IF rH < 0.01 THEN rH := 0.35; END_IF
    IF rF < 0.01 THEN rF := 0.05; END_IF
    IF rLow < 0.01 THEN rLow := 0.48; END_IF
    rSum := rR + rRing + rH + rF + rLow;
    IF rSum > 0.01 THEN
        rR := rR / rSum;
        rRing := rRing / rSum;
        rH := rH / rSum;
        rF := rF / rSum;
        rLow := rLow / rSum;
    END_IF
    rOS := rOvershoot;
    IF rOS <= 0.0 THEN rOS := 0.10; END_IF
    rPeakOS := rPMax + rOS * (rPMax - rPMin);

ELSE
    // 正弦无段：把变量清成无害默认值
    rR := 0.0;
    rH := 0.0;
    rF := 0.0;
    rRing := 0.0;
    rPeakOS := rPMax;
END_CASE

// 段宽输出 (供下游 FB_ILC)
rSegRise   := rR;
rSegRing   := rRing;
rSegHold   := rH;
rSegFall   := rF;
rPeakOSOut := rPeakOS;


// ============================================================
// 主波形计算
// ============================================================
rTarget := FN_PulseWave(
    rPhaseIn := rPhase,
    rPMin := rPMin, rPMax := rPMax, iWaveType := iWaveType,
    rR := rR, rH := rH, rF := rF, rRing := rRing, rPeakOS := rPeakOS);


// ============================================================
// MFF 超前目标
// 用超前相位 (φ + N·Δφ) 计算未来 N 步的目标，给前馈控制器提前响应
// ============================================================
rTargetLeadPrev := rTargetLeadLast;

IF nMffLeadSteps > 0 THEN
    rPhaseLead := rPhaseAcc + INT_TO_REAL(nMffLeadSteps) * rFrequency * rDt;
    IF rPhaseLead >= 1.0 THEN rPhaseLead := rPhaseLead - 1.0; END_IF

    rTargetLead := FN_PulseWave(
        rPhaseIn := rPhaseLead,
        rPMin := rPMin, rPMax := rPMax, iWaveType := iWaveType,
        rR := rR, rH := rH, rF := rF, rRing := rRing, rPeakOS := rPeakOS);
ELSE
    rTargetLead := rTarget;
END_IF


// ============================================================
// ARP1383C 误差包络 (三相位采样 + 压力容差带)
//
// 包络生成原理:
//   设当前相位 φ，时间容差 Δt = rEnvPctT × 周期 (归一化即 rEnvPctT)
//   在 φ-Δt, φ, φ+Δt 三个相位采样目标值，取 max/min:
//     P_upper(φ) = max{P_nom(φ'), φ' ∈ {φ-Δt, φ, φ+Δt}} + ΔP
//     P_lower(φ) = min{P_nom(φ'), φ' ∈ {φ-Δt, φ, φ+Δt}} - ΔP
//   其中压力容差 ΔP = rEnvPctP × PMax
//
//   这样:
//     正弦波 — 三点采样近似相等，包络 ≈ 主波形 ± ΔP
//     梯形波 — 上升/下降沿处三点跨越平台，包络自动张开 (上沿提前+晚段)
//     水锤波 — 过冲峰区采样到 P_OS，包络上沿包住尖峰
//
// ARP1383C 默认: ΔP = 5%·PMax, Δt = 10% 周期
// ============================================================
rEnvDP := rEnvPctP * rPMax;

// 三相位的早相 / 晚相，循环回卷到 [0, 1)
rPhaseEarly := rPhase + rEnvPctT;
IF rPhaseEarly >= 1.0 THEN rPhaseEarly := rPhaseEarly - 1.0; END_IF
rPhaseLate := rPhase - rEnvPctT;
IF rPhaseLate < 0.0 THEN rPhaseLate := rPhaseLate + 1.0; END_IF

rTargetEarly := FN_PulseWave(
    rPhaseIn := rPhaseEarly,
    rPMin := rPMin, rPMax := rPMax, iWaveType := iWaveType,
    rR := rR, rH := rH, rF := rF, rRing := rRing, rPeakOS := rPeakOS);
rTargetLate := FN_PulseWave(
    rPhaseIn := rPhaseLate,
    rPMin := rPMin, rPMax := rPMax, iWaveType := iWaveType,
    rR := rR, rH := rH, rF := rF, rRing := rRing, rPeakOS := rPeakOS);

// max / min over the three samples
rEnvMax := rTarget;
IF rTargetEarly > rEnvMax THEN rEnvMax := rTargetEarly; END_IF
IF rTargetLate > rEnvMax THEN rEnvMax := rTargetLate; END_IF
rEnvMin := rTarget;
IF rTargetEarly < rEnvMin THEN rEnvMin := rTargetEarly; END_IF
IF rTargetLate < rEnvMin THEN rEnvMin := rTargetLate; END_IF

rTargetUpper := rEnvMax + rEnvDP;
rTargetLower := rEnvMin - rEnvDP;
IF rTargetLower < 0.0 THEN rTargetLower := 0.0; END_IF
IF rTargetUpper > 50.0 THEN rTargetUpper := 50.0; END_IF


// ============================================================
// 首次运行初始化 (避免起步瞬间 dP/dt 出现伪大值)
// ============================================================
IF bFirstRun THEN
    rTargetPrev := rTarget;
    rTargetLeadPrev := rTargetLead;
    bFirstRun := FALSE;
END_IF

rTargetLast := rTarget;
rTargetLeadLast := rTargetLead;

iIdxCounter := iIdxCounter + 1;

CASE Channel OF
	0:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[0];
	1:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[1];	
	2:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[2];
	3:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[3];
	4:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[4];
	5:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[5];	
	6:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[6];
	7:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[7];
	8:
	HighSpeedChannel := Axis.Pos_KP;
	9:
	HighSpeedChannel := Axis.Pos_Ki;	
	10:
	HighSpeedChannel := Axis.Pos_VelocityFFCoefficient;		
	11:
	HighSpeedChannel := Axis.Pos_VelocityFWCoefficient;		
	12:
	HighSpeedChannel := Axis.Pressure_KP;
	13:
	HighSpeedChannel := Axis.Pressure_Ki;	
	14:
	HighSpeedChannel := Axis.Force_KP;		
	15:
	HighSpeedChannel := Axis.Force_Ki;		
	16:
	HighSpeedChannel := Axis.Force_VelocityFFCoefficient;
	17:
	HighSpeedChannel := Axis.Force_ForceFFCoefficient;	
	18:
	HighSpeedChannel := Axis.Force_VelocityFWCoefficient;		
	19:
	HighSpeedChannel := Axis.PIDout;		
	20:
	HighSpeedChannel := Axis.PositionCMD;		
	21:
	HighSpeedChannel := Axis.PressureCMD;		
	22:
	HighSpeedChannel := Axis.ForceCMD;
	23:
	HighSpeedChannel := Axis.PositionError;	
	24:
	HighSpeedChannel := Axis.PressureError;		
	25:
	HighSpeedChannel := Axis.ForceError;	


END_CASE

CASE Mode OF 
	//默认
	 1: //一阶惯性
	   //G(s) = K / (T*s + 1)
       // G(s) 差分方程 = (K*Ts*z + K*Ts)/((2*T + Ts)*z + Ts - 2*T)
	   y := (K*Ts*u + K*Ts*u_1-y_1*(Ts-2*T))/(2*T + Ts);
	   y_1:=y;
	   u_1:=u;
	 2://二阶方程
	  tn2 := T * T;
	  int1(X := u * K / tn2 - I1 * 0.5 * D / T - I2 / TN2, Y := I1);
	  int2(X := I1,Y := I2);
	  y := I2;	
END_CASE

// ============================================================
// 每周期首先执行数据打包（PLC→PC）
// 这是最先执行的步骤：将 PLC 当前所有需要上传的状态、数据
// 写入 INPUT_REGISTER 缓冲区，为后续 TCP_Write 发送做准备。
// 必须在 TCP_Write 之前调用，否则发送的是上一周期的旧数据。
// ============================================================
TCP_PLC_to_PC();
(*
// ============================================================
// 初始化：动态计算 FOR 循环上界
// mark_for_mun = SIZEOF(write_mark_bool) - 1
// 仅在首次执行时计算一次，后续周期不再重复计算（因为数组大小固定）
// ============================================================
IF initial_run THEN
    mark_for_mun := SIZEOF(write_mark_bool) - 1;
END_IF

// ============================================================
// 服务器异常后 FT 自动重启使能
// 容错重启机制：
//   当 TCP_Server_open 出现错误（xError=TRUE）或句柄丢失（hServer=0）时，
//   blink_server 开始闪烁 server_en（反复 FALSE/TRUE），产生上升沿触发重新打开服务器。
//   当服务器恢复正常（xError=FALSE 且 hServer≠0）时，server_en 保持 TRUE，闪烁停止。
// ============================================================
IF TCP_Server_open.xError OR (TCP_Server_open.hServer = 0) THEN
    blink_server(i_enable := TRUE, out_bool => server_en);
ELSE
    server_en := TRUE;
    blink_server(i_enable := FALSE);
END_IF

// ============================================================
// 启动/重启 TCP Server
// 服务器生命周期第一步：open（打开套接字）
//   - xEnable 上升沿触发：绑定 IP_ADR_server + ServerPORT，开始监听
//   - 输出 xBusy=TRUE 表示正在监听，hServer 为服务器句柄（供 TCP_Connection 使用）
//   - 输出 xDone=TRUE 表示服务器已关闭（xEnable 下降沿时）
//   - 输出 xError=TRUE 表示打开失败
// 当 connectNG（连接丢失）或首次运行时，重新调用以确保服务器处于监听状态
// ============================================================
IF connectNG OR initial_run THEN
    cishuhaha := cishuhaha + 1;
    TCP_Server_open(
        xEnable  := server_en,
        ipAddr   := IP_ADR_server,
        uiPort   := ServerPORT,
        xDone    => ,
        xBusy    => ,
        xError   => ,
        eError   => ,
        hServer  => );
END_IF

// ============================================================
// 检测客户端连接
// 服务器生命周期第二步：accept（接受客户端连接）
//   - xEnable 持续为 TRUE 时，TCP_Connection 等待客户端连接
//   - hServer 由 TCP_Server_open 提供，标识在哪个服务器上等待连接
//   - 连接成功后 xActive=TRUE，hConnection 为连接句柄（供 Read/Write 使用）
//   - xError=TRUE 表示连接失败
//   re_connection 检测连接丢失的上升沿（connectNG 从 FALSE→TRUE），
//   短暂禁用 TCP_Connection 以触发重新等待连接
// ============================================================
connectNG := (TCP_Connection.hConnection = 0);
re_connection(CLK := connectNG);

TCP_Connection(
    xEnable     := TCP_Server_open.xBusy AND NOT re_connection.Q,
    hServer     := TCP_Server_open.hServer,
    xDone       => ,
    xBusy       => ,
    xError      => ,
    eError      => ,
    xActive     => ,
    hConnection => );

// ============================================================
// READ：接收上位机数据 → HOLDING_REGISTER
// 服务器生命周期第三步：read（读取数据）
//   - xEnable 持续为 TRUE 时，每周期尝试从已建立的连接中读取数据
//   - hConnection 由 TCP_Connection 提供
//   - szSize 指定读取长度 = HOLDING_REGISTER 的大小
//   - pData 指向 HOLDING_REGISTER 的地址，数据直接写入该缓冲区
//   - xReady=TRUE 表示有新数据到达（可在此触发解析）
//   - xDone=TRUE 表示读取完成
//   - 读取到的数据将由最后的 TCP_PC_to_PLC() 进行解析
// ============================================================
server_read(
    xEnable     := TCP_Connection.xActive,
    hConnection := TCP_Connection.hConnection,
    szSize      := SIZEOF(TCP_PC_to_PLC.HOLDING_REGISTER),
    pData       := ADR(TCP_PC_to_PLC.HOLDING_REGISTER),
    xDone       => ,
    xBusy       => ,
    xError      => ,
    eError      => ,
    xReady      => ,
    szCount     => );

// ============================================================
// WRITE：发送 INPUT_REGISTER → 上位机（每周期写一次，交替触发）
// 服务器生命周期第四步：write（写入数据）
//   使用 FOR 循环 + write_mark_bool 交替触发方案：
//   - i_for=0: write_mark_bool[0]=FALSE → xExecute=FALSE（下降沿，为下次上升沿做准备）
//   - i_for=1: write_mark_bool[1]=TRUE  → xExecute=TRUE（上升沿，触发本次发送）
//   每个扫描周期内，同一个 server_write 功能块被调用两次：
//     第一次(FALSE)复位内部状态，第二次(TRUE)产生上升沿触发发送。
//   这是因为 NBS.TCP_Write 的 xExecute 需要上升沿触发，
//   如果 xExecute 始终为 TRUE 则只会发送一次，不会持续发送。
//   交替触发确保每个 10ms 周期都能成功发送一帧数据。
//   发送的数据是 INPUT_REGISTER，由 TCP_PLC_to_PC() 在周期开始时打包完毕。
// ============================================================
FOR i_for := 0 TO mark_for_mun DO
    server_write(
        xExecute    := TCP_Connection.xActive AND write_mark_bool[i_for],
        udiTimeOut  := 3008,
        hConnection := TCP_Connection.hConnection,
        szSize      := SIZEOF(TCP_PLC_to_PC.INPUT_REGISTER),
        pData       := ADR(TCP_PLC_to_PC.INPUT_REGISTER),
        xDone       => write_done_bool[i_for],
        xBusy       => write_busy_bool[i_for],
        xError      => write_error_bool[i_for],
        eError      => );
END_FOR


// ============================================================
// 结束初始化标志
// ============================================================
IF initial_run THEN
    initial_run := FALSE;
END_IF

// ============================================================
// 解析上位机数据（PC→PLC）
// 这是最后执行的步骤：从 HOLDING_REGISTER 中提取上位机下发的
// 各项参数（如设定值、命令等），写入对应的 PLC 变量。
// 必须在 TCP_Read 之后调用，因为此时 HOLDING_REGISTER 中才有最新接收的数据。
// 执行顺序总结：打包(TCP_PLC_to_PC) → 发送(TCP_Write) → 接收(TCP_Read) → 解析(TCP_PC_to_PLC)
// ============================================================

*)
// ============================================================
// 10 ms 帧计数递增（PLC→PC 帧计数器）
// FrameTick 每周期 +1，写入 PP_FrameCounter_PLC，
// 上位机可通过此值判断 PLC 是否在正常运行和通讯
// ============================================================
FrameTick := FrameTick + 1;
GVL_PulsePressure.PP_FrameCounter_PLC := DINT_TO_REAL(FrameTick);

TCP_PC_to_PLC();

{*
26.01为剂侧产品端低压力传感器
27.01为剂侧产品端15MPa高压力传感器
*}

//剂侧产品端压力 — 默认使用26.01低压传感器(可根据需要切换27.01)
PP_Oil_ActualPressure := GVL_PulsePressure.PP_Dev_Pressure_26_01;
Oil_Pressure_Filter(in:= PP_Oil_ActualPressure,t:= T#100MS);
GVL_PulsePressure.PP_Oil_ActualPressure := Oil_Pressure_Filter.out;


//方向系数
PWMotion.FPGAData.Axis1.OutputCoefficient := 1;


// ============================================================
// 循环计数清零（上升沿检测，任何状态下都执行）
// PC写入CycleReset=1.0触发清零，清零后PC应写回0.0
// ============================================================
IF GVL_PulsePressure.PP_Oil_CycleReset = 1.0 AND NOT bOilCycleResetPrev THEN
    GVL_PulsePressure.PP_Oil_CyclesDone := 0.0;
    GVL_PulsePressure.PP_TotalCyclesDone := 0.0;
END_IF
bOilCycleResetPrev := (GVL_PulsePressure.PP_Oil_CycleReset = 1.0);

// ============================================================
// PC命令解析
// PP_SysCommand: 0=空闲 1=冲洗排气 2=运行 3=停止
// 命令变化时触发状态切换
// ============================================================
iCmd := REAL_TO_INT(GVL_PulsePressure.PP_SysCommand);
bCmdChanged := (iCmd <> iCmdPrev);
iCmdPrev := iCmd;

// 命令变化时执行状态切换
IF bCmdChanged THEN
    // 进入冲洗或运行前复位所有控制器 (原 InitializeControllers 方法)
    // - fbWaveGen_O 清相位累加器、计数器
    // - fbPID_O 清积分、微分
    // - fbILC_O 清学习历史
    IF iCmd = 1 OR iCmd = 2 THEN
        fbWaveGen_O(bReset := TRUE);
        fbPID_O(bReset := TRUE);
        fbILC_O(bReset := TRUE);
        rPeakPressure_O := 0.0;
        rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
    END_IF

    CASE iCmd OF
        0: // 回空闲
            iState := 0;
        1: // 冲洗排气
            rFlushDuration := GVL_PulsePressure.PP_FlushDuration;
            rFlushOutput := GVL_PulsePressure.PP_FlushValveOutput;
            IF rFlushOutput < 0.5 THEN rFlushOutput := 2.0; END_IF
            IF rFlushOutput > 5.0 THEN rFlushOutput := 5.0; END_IF
            rFlushTimer := 0.0;
            iState := 1;
        2: // 运行（伺服阀直接控制压力，无需油缸到位检查/预加压）
		    rFlushTimer := 0.0;
            iState := 3;
        3: // 停止
            rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
            iState := 4;
    END_CASE
    GVL_PulsePressure.PP_StateReady := 0.0;
END_IF

// ============================================================
// 通道选择（只有油路）
// 始终走剂侧测试: 油路通断阀 10.01/10.03 打开
// 实际硬件驱动由 PRG_DeviceControl（待重写）从 GVL_GPIO 直接读取
// ============================================================



// ============================================================
// 计算实际PMin（直接使用上位机设定值，0即为0MPa）
// ============================================================
rActualPMin_O := GVL_PulsePressure.PP_Oil_MinPressure;
IF rActualPMin_O < 0.0 THEN rActualPMin_O := 0.0; END_IF
IF rActualPMin_O >= GVL_PulsePressure.PP_Oil_TargetPressure THEN
    rActualPMin_O := GVL_PulsePressure.PP_Oil_TargetPressure * 0.9;
END_IF

// ============================================================
// 状态机
// ============================================================
CASE iState OF

// ------------------------------------------------------------
// 状态0: 空闲
// 所有控制输出清零，等待PC写入新命令
// ------------------------------------------------------------
0:
    bRunning := FALSE;
    rUTotal_O := 0.0;
    GVL_PulsePressure.PP_SysState := 0.0;  // 空闲
    GVL_PulsePressure.PP_FlushTimeRemaining := 0.0;
    GVL_PulsePressure.PP_StateReady := 0.0;

// ------------------------------------------------------------
// 状态1: 冲洗排气 — 低压循环排出管路中的空气
// PLC置StateReady=1通知PC冲洗完成，由PC决定何时发下一命令。
// ------------------------------------------------------------
1:
    bRunning := TRUE;
    GVL_PulsePressure.PP_SysState := 1.0;  // 冲洗排气

    // 冲洗计时
    rFlushTimer := rFlushTimer + rDt;
    GVL_PulsePressure.PP_FlushTimeRemaining := rFlushDuration - rFlushTimer;
    IF GVL_PulsePressure.PP_FlushTimeRemaining < 0.0 THEN
        GVL_PulsePressure.PP_FlushTimeRemaining := 0.0;
    END_IF

    // 直接伺服阀控制系统: 冲洗排气期间阀口保持小开度排气, 不做油缸往复
    PWMOTION.FPGAData.Axis1.Output_ManualSet := rFlushOutput * 10;

    // 冲洗时间到 → 置就绪标志，通知 PC 发下一命令
    IF rFlushTimer >= rFlushDuration THEN
        GVL_PulsePressure.PP_FlushTimeRemaining := 0.0;
        GVL_PulsePressure.PP_StateReady := 1.0;
    END_IF
// ------------------------------------------------------------
// 状态3: 运行 — MFF + ILC + PID 复合控制
// 此状态下执行完整的6步控制流水线:
//   1) 波形生成 → 2) 计算跟踪误差 → 3) MFF前馈
//   → 4) ILC前馈 → 5) PID反馈 → 6) 三路叠加
// ============================================================
3:
    bRunning := TRUE;
    GVL_PulsePressure.PP_SysState := 3.0;  // 运行

    // ==================== 油路控制 (ILC 修指令 + PID 反馈) ====================

    // ---- 1. 波形生成 (含 ARP1383C 误差包络) ----
    fbWaveGen_O(
        bEnable       := TRUE,
        rPMin         := rActualPMin_O,
        rPMax         := GVL_PulsePressure.PP_Oil_TargetPressure,
        rFrequency    := GVL_PulsePressure.PP_Oil_Frequency,
        iWaveType     := REAL_TO_INT(GVL_PulsePressure.PP_Oil_WaveType),
        rRisePct      := GVL_PulsePressure.PP_Oil_RisePct,
        rHoldPct      := GVL_PulsePressure.PP_Oil_HoldPct,
        rFallPct      := GVL_PulsePressure.PP_Oil_FallPct,
        rOvershoot    := GVL_PulsePressure.PP_Oil_Overshoot,
        rRingPct      := GVL_PulsePressure.PP_Oil_RingPct,
        rLowDwellPct  := GVL_PulsePressure.PP_Oil_LowDwellPct,
        rDt           := rDt,
        bReset        := FALSE,
        nMffLeadSteps := 0,    // 已移除 MFF, 不再需要超前相位
        rEnvPctP      := GVL_PulsePressure.PP_Oil_EnvPctP,
        rEnvPctT      := GVL_PulsePressure.PP_Oil_EnvPctT
    );

    GVL_PulsePressure.PP_Oil_SetpointPressure := fbWaveGen_O.rTarget;

    // 包络输出 → GVL (供 HMI 绘制 ARP1383C 容差带)
    GVL_PulsePressure.PP_Oil_TargetUpper := fbWaveGen_O.rTargetUpper;
    GVL_PulsePressure.PP_Oil_TargetLower := fbWaveGen_O.rTargetLower;

    GVL_PulsePressure.PP_Oil_WavePhase    := fbWaveGen_O.rPhase * 360.0;
    GVL_PulsePressure.PP_Oil_Frequency_FB := GVL_PulsePressure.PP_Oil_Frequency;

    // 周期计数 + 峰值锁存
    IF fbWaveGen_O.bNewCycle THEN
        GVL_PulsePressure.PP_Oil_CyclesDone   := GVL_PulsePressure.PP_Oil_CyclesDone + 1.0;
        GVL_PulsePressure.PP_TotalCyclesDone  := GVL_PulsePressure.PP_TotalCyclesDone + 1.0;
        GVL_PulsePressure.PP_Oil_PeakPressure := rPeakPressure_O;
        rPeakPressure_O := 0.0;
    END_IF
    IF GVL_PulsePressure.PP_Oil_ActualPressure > rPeakPressure_O THEN
        rPeakPressure_O := GVL_PulsePressure.PP_Oil_ActualPressure;
    END_IF

    // ---- 2. ILC 指令修正 (MPa 域) ----
    // 新架构: ILC 不再作为电压前馈分量, 而是学习对目标指令本身的修正量,
    // 然后 PID 跟踪修正后的目标. 这样:
    //   - 单位一致: rOutput 是 MPa 级修正, 加到 rTarget (MPa) 上
    //   - 物理意义清晰: 学到的是 "为了让实际压力达到 rTarget, 阀控制器应该追的虚拟目标"
    //   - 闭环稳定性由 PID 单独保证, ILC 只是循环间慢学习
    // nWaveType 与 FB_WaveformGen 同编码: 0=正弦 / 1=梯形 / 2=水锤波
    // 段宽来自 fbWaveGen_O 已归一化的 rSegRise / rSegRing / rSegHold / rSegFall
    fbILC_O(
        bEnable         := (GVL_PulsePressure.PP_Oil_ILC_Enable >= 0.5),
        rTargetRaw      := fbWaveGen_O.rTarget,
        rActual         := GVL_PulsePressure.PP_Oil_ActualPressure,
        iPointIndex     := fbWaveGen_O.iPointIndex,
        iPointsPerCycle := fbWaveGen_O.iPointsPerCycle,
        bNewCycle       := fbWaveGen_O.bNewCycle,
        bReset          := FALSE,
        iMaxIterations  := REAL_TO_INT(GVL_PulsePressure.PP_Oil_ILC_MaxIter),
        rLearningRate   := GVL_PulsePressure.PP_Oil_ILC_LearningRate,
        iWaveTypeIn     := REAL_TO_INT(GVL_PulsePressure.PP_Oil_WaveType),
        rWHPMaxTarget   := GVL_PulsePressure.PP_Oil_TargetPressure,
        rWHRiseFrac     := fbWaveGen_O.rSegRise,
        rWHRingFrac     := fbWaveGen_O.rSegRing,
        rWHHoldFrac     := fbWaveGen_O.rSegHold,
        rWHFallFrac     := fbWaveGen_O.rSegFall,
        rEnvUpper       := fbWaveGen_O.rTargetUpper,  // ARP1383C 包络: 在包络内停学习, 越界才学习
        rEnvLower       := fbWaveGen_O.rTargetLower
    );
    rIlcCorrection_O := fbILC_O.rOutput;                                 // MPa
    rTargetCorrected_O := fbWaveGen_O.rTarget + rIlcCorrection_O;        // MPa
    GVL_PulsePressure.PP_Oil_ILC_Output    := rIlcCorrection_O;
    GVL_PulsePressure.PP_Oil_ILC_Iteration := INT_TO_REAL(fbILC_O.iIteration);

    // ---- 3. 跟踪误差 (基于 ILC 修正后的目标) ----
    rError_O := rTargetCorrected_O - GVL_PulsePressure.PP_Oil_ActualPressure;
    GVL_PulsePressure.PP_Oil_PressureError := rError_O;

    // ---- 4. PID 反馈 ----
    fbPID_O(
        bEnable := TRUE,
        rError  := rError_O,
        rDt     := rDt,
        bReset  := FALSE,
        rPID_Kp := GVL_PulsePressure.PP_Oil_PID_Kp,
        rPID_Ki := GVL_PulsePressure.PP_Oil_PID_Ki,
        rPID_Kd := GVL_PulsePressure.PP_Oil_PID_Kd
    );
    rUPid_O := fbPID_O.rOutput;
    GVL_PulsePressure.PP_Oil_PID_Output   := rUPid_O;
    GVL_PulsePressure.PP_Oil_PID_Integral := fbPID_O.rPID_I;

    // ---- 5. 阀控电压 = PID 输出 (无 MFF 前馈) ----
    rUTotal_O := rUPid_O;
    IF rUTotal_O >  10.0 THEN rUTotal_O :=  10.0; END_IF
    IF rUTotal_O < -10.0 THEN rUTotal_O := -10.0; END_IF

    PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O * 10;

    // 检查目标循环数（到达后自动停止）
    IF GVL_PulsePressure.PP_Oil_TargetCycles > 0.0 THEN
        IF GVL_PulsePressure.PP_Oil_CyclesDone >= GVL_PulsePressure.PP_Oil_TargetCycles THEN
            rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
            iState := 4;
        END_IF
    END_IF

// ------------------------------------------------------------
// 状态4: 停止中 — 缓慢卸压
// 停止斜坡机制说明:
//   进入状态4时 (命令 3) rStopRampVal_O 已在 CASE iCmd 中被初始化为当前实际压力。
//   每个控制周期(1ms)按 rStopRampRate=5MPa/s 递减目标值，
//   并用比例控制(rStopRampKp=2.0)跟踪递减目标值。
//   这实现了从当前压力到零的平滑下降，避免直接关闭阀门导致的
//   水锤效应或压力冲击。当实际压力降到0.5MPa以下时认为卸压完成，
//   返回空闲状态(状态0)。
// ------------------------------------------------------------
4:
    GVL_PulsePressure.PP_SysState := 4.0;  // 停止中

    // 油路卸压
    IF GVL_PulsePressure.PP_Oil_ActualPressure > 0.5 THEN
        // 斜坡目标值每ms递减 rStopRampRate*0.001 = 0.005MPa
        // 即5MPa/s的卸压速率
        rStopRampVal_O := rStopRampVal_O - rStopRampRate * rDt;
        IF rStopRampVal_O < 0.0 THEN rStopRampVal_O := 0.0; END_IF
        rStopRampErr_O := rStopRampVal_O - GVL_PulsePressure.PP_Oil_ActualPressure;
        PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O := rStopRampKp * rStopRampErr_O;
    ELSE
        PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O := 0.0;
    END_IF

    // 卸压完成 → 置就绪标志，通知PC（PC发命令0回空闲）
    IF GVL_PulsePressure.PP_Oil_ActualPressure < 0.5 THEN
        GVL_PulsePressure.PP_StateReady := 1.0;
    END_IF

// ------------------------------------------------------------
// 状态5: 故障
// 由高压保护触发，所有输出强制清零
// PC发命令0即可恢复到空闲状态
// ------------------------------------------------------------
5:
    rUTotal_O := 0.0;
    PWMOTION.FPGAData.Axis1.Output_ManualSet := 0;
    GVL_PulsePressure.PP_SysState := 5.0;  // 故障

END_CASE

// ============================================================
// 高压保护 — 任何状态下都执行，优先级高于状态机
// 说明: 当实际压力超过设定的限值(HighLimit)时，
//   1) 强制控制输出为0V，并打开回油阀快速泄压
//   2) 立即将状态机切换到故障状态(状态5)
//   此保护在CASE语句之后执行，因此会覆盖任何状态下的控制输出，
//   确保即使运行状态中出现超压也能立即响应。
//   高压保护条件: HighLimit > 0 且 实际压力 > HighLimit
//   HighLimit > 0的检查是为了防止未设定限值时误触发
// ============================================================
IF GVL_PulsePressure.PP_Oil_ActualPressure > GVL_PulsePressure.PP_Oil_HighLimit
   AND GVL_PulsePressure.PP_Oil_HighLimit > 0.0 THEN
    PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O := 0.0;
	GVL_PulsePressure.PP_Dev_PneValve_YV7 := 1.0;  // 待 PRG_DeviceControl 驱动 YV7 硬件
    iState := 5;
ELSE
	GVL_PulsePressure.PP_Dev_PneValve_YV7 := 0.0;
END_IF

// ============================================================
// 急停保护 — 任何状态下都执行
// 急停时强制切到停止状态(状态4)进行斜坡卸压
// ============================================================
IF GVL_PulsePressure.PP_EmergencyStop = 1.0 AND iState <> 0 AND iState <> 4 AND iState <> 5 THEN
    rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
    iState := 4;
END_IF

// ============================================================
// 输出到全局变量
// ============================================================
// 总控制输出限幅: ±10V 对应伺服阀最大驱动范围
IF rUTotal_O > 10.0 THEN rUTotal_O := 10.0; END_IF
IF rUTotal_O < -10.0 THEN rUTotal_O := -10.0; END_IF

GVL_PulsePressure.PP_Oil_ControlOutput := rUTotal_O;

// ===================================================================
// TCP HOLDING_REGISTER 地址布局 (PC → PLC, V5.0)
// ===================================================================
// 设计原则:
//   - 每节内字段从基址连续紧排, 节尾留大块预留
//   - 节边界对齐 32W 倍数, 便于上位机分块读写
//   - 字段一旦发布不再挪位; 新字段从节末预留区追加
// ===================================================================
// [A] 系统控制    0   – 31    (32 W;  6 字段 = 12 W, 余 20 W)
// [B] 冲洗排气    32  – 47    (16 W;  2 字段 =  4 W, 余 12 W)
// [C] 油路波形    48  – 95    (48 W; 15 字段 = 30 W, 余 18 W)
// [D] 控制器      96  – 127   (32 W;  6 字段 = 12 W, 余 20 W)  ILC + PID
// [E] 液压站     128 – 159    (32 W;  4 字段 =  8 W, 余 24 W)
// [F] IO 控制    160 – 191    (32 W;  2 字段 =  4 W, 余 28 W)
// [G] 设备控制   192 – 255    (64 W; 由 PRG_DeviceControl 解析)
// [Z] 未来扩展   256 – 1999
// ===================================================================


// ===== [A] 系统控制 (0-31) =====
i := 0;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_FrameCounter_PC := TwoWord_to_Float.Output;        // 0-1: 上位机帧计数器(心跳)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_SysCommand := TwoWord_to_Float.Output;             // 2-3: 系统命令 0=空闲 1=冲洗 2=运行 3=停止
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_AlarmReset := TwoWord_to_Float.Output;             // 4-5: 报警复位
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Enable := TwoWord_to_Float.Output;                 // 6-7: 系统使能
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_EmergencyStop := TwoWord_to_Float.Output;          // 8-9: 急停
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_HeartbeatTimeout := TwoWord_to_Float.Output;       // 10-11: 心跳超时(s)
i := i + 2;

// 12-31: 保留 (10 字段)


// ===== [B] 冲洗排气 (32-47) =====
i := 32;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_FlushDuration := TwoWord_to_Float.Output;          // 32-33: 冲洗持续时间(s); 0=跳过冲洗
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_FlushValveOutput := TwoWord_to_Float.Output;       // 34-35: 冲洗阀门输出(V); 默认 2.0
i := i + 2;

// 36-47: 保留 (6 字段)


// ===== [C] 油路波形 (48-95) =====
i := 48;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_WaveType := TwoWord_to_Float.Output;           // 48-49: 波形类型 0=正弦 1=梯形 2=ARP1383 水锤
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_TargetPressure := TwoWord_to_Float.Output;     // 50-51: 目标峰值压力 PMax (MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_MinPressure := TwoWord_to_Float.Output;        // 52-53: 最低压力 PMin (MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_Frequency := TwoWord_to_Float.Output;          // 54-55: 脉冲频率 (Hz)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_HighLimit := TwoWord_to_Float.Output;          // 56-57: 高压保护限值 (MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_TargetCycles := TwoWord_to_Float.Output;       // 58-59: 目标循环次数
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_RisePct := TwoWord_to_Float.Output;            // 60-61: 上升段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_HoldPct := TwoWord_to_Float.Output;            // 62-63: 保压段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_FallPct := TwoWord_to_Float.Output;            // 64-65: 下降段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_Overshoot := TwoWord_to_Float.Output;          // 66-67: 水锤波过冲幅值占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_RingPct := TwoWord_to_Float.Output;            // 68-69: 水锤波过冲后稳定段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_LowDwellPct := TwoWord_to_Float.Output;        // 70-71: 水锤波低保持段占比
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_CycleReset := TwoWord_to_Float.Output;         // 72-73: 循环计数清零命令
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_EnvPctP := TwoWord_to_Float.Output;            // 74-75: ARP1383C 包络压力容差 ×PMax (默认 0.05)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_EnvPctT := TwoWord_to_Float.Output;            // 76-77: ARP1383C 包络时间容差 ×周期 (默认 0.10)
i := i + 2;

// 78-95: 保留 (9 字段)


// ===== [D] 控制器: ILC + PID (96-127) =====
i := 96;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_ILC_Enable := TwoWord_to_Float.Output;         // 96-97: ILC 使能
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_ILC_MaxIter := TwoWord_to_Float.Output;        // 98-99: ILC 最大迭代次数
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_ILC_LearningRate := TwoWord_to_Float.Output;   // 100-101: ILC 学习率 (0~1)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_PID_Kp := TwoWord_to_Float.Output;             // 102-103: PID 比例增益 Kp (V/MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_PID_Ki := TwoWord_to_Float.Output;             // 104-105: PID 积分增益 Ki (V/MPa/s)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Oil_PID_Kd := TwoWord_to_Float.Output;             // 106-107: PID 微分增益 Kd (V·s/MPa)
i := i + 2;

// 108-127: 保留 (10 字段)


// ===== [E] 液压站 (128-159) =====
i := 128;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Hydro_HighLimit := TwoWord_to_Float.Output;        // 128-129: 液压站高压限值 (MPa)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Hydro_TempLimit := TwoWord_to_Float.Output;        // 130-131: 油温保护限值 (°C)
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Hydro_PumpCmd := TwoWord_to_Float.Output;          // 132-133: 液压泵启停命令
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Hydro_MotorSpeed := TwoWord_to_Float.Output;       // 134-135: 电机转速设定 (rpm)
i := i + 2;

// 136-159: 保留 (12 字段)


// ===== [F] IO 控制 (160-191) =====
i := 160;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_IO_OutputBits := TwoWord_to_Float.Output;          // 160-161: 数字量输出控制
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_IO_OilCircuitSel := TwoWord_to_Float.Output;       // 162-163: 油路选通
i := i + 2;

// 164-191: 保留 (14 字段)


// ===== [G] 设备控制 (192-255) =====
// 该区域的解析由 PRG_DeviceControl（待重写）负责。原始 HOLDING_REGISTER
// 直接保留在缓冲区, 新 PRG_DeviceControl 可直接按 bit/Float 访问解析。
//
// 建议地址分配 (占位约定):
//   192-193 : bit-packed 泵启停 (SMP/XH/HR1/HR2 × Start/Stop/Reset, 12 bits)
//   194-195 : bit-packed Pne_Valve YV1-YV13 (13 bits)
//   196-205 : 保留 (5 字段)
//   206-207 : SMP 压力设定 (MPa)
//   208-209 : SMP 流量设定
//   210-211 : HR_Pump1 频率设定
//   212-213 : HR_Pump2 频率设定
//   214-255 : 保留 (21 字段)


// ===== [Z] 256-1999: 未来扩展 =====

//模拟量采集函数
//输入信号在正常范围内
IF Input>=In_Lo_Limit AND Input<=In_Hi_Limit THEN
   Collect_Out := ((Out_Hi_Limit - Out_Lo_Limit) * (Input - In_Lo_Limit) / (In_Hi_Limit - In_Lo_Limit)) + Out_Lo_Limit; //包含有隐式转换
END_IF

//该限幅--仅在单极性下适用
//输入信号低值_限幅
IF Input<In_Lo_Limit THEN
	Collect_Out :=Out_Lo_Limit ;
END_IF

//输入信号高值_限幅
IF Input>In_Hi_Limit THEN
	Collect_Out :=Out_Hi_Limit;
END_IF

//模拟量模块输出函数
//设定在正常范围内
IF Input>=In_Lo_Limit AND Input<=In_Hi_Limit THEN
   OutPut := REAL_TO_INT ( ( ( Out_Hi_Limit - Out_Lo_Limit ) * ( Input - In_Lo_Limit ) / ( In_Hi_Limit - In_Lo_Limit ) ) + Out_Lo_Limit ) ;
END_IF
//输出低限_限幅
IF Input<In_Lo_Limit  THEN
   OutPut := Out_Lo_Limit;
END_IF
//输出高限_限幅
IF  Input>In_Hi_Limit THEN
	OutPut := Out_Hi_Limit;
END_IF

AddValue:=Incre/DINT_TO_REAL((1000/TIME_TO_DINT(Cycle))); //根据程序执行周期和设定的每秒增量计算每个扫描周期应该增加的△Add

IF Enable=TRUE THEN
	     //*******************************************************//
		 {判断输入的数据是否有变化}
         IF InPut<>TempVar[0] THEN   
             bChange_Flag:=TRUE;
         ELSE 
             bChange_Flag:=FALSE;
         END_IF
         CF:=bChange_Flag;//数据变化信号输出	

         RTRIGInst_1(CLK:=bChange_Flag);  //检测输入信号上升沿 
         IF RTRIGInst_1.Q THEN
	         TempVar[1]:=TempVar[0];
         END_IF

         TempVar[0]:=InPut;
        //*******************************************************//

		{将相邻两次输入的数据临时保存}
        TempVar[3]:=TempVar[0]; //新输入的数据
        TempVar[4]:=TempVar[1]; //变化前的数据

        K:=TempVar[3] - TempVar[4];   //斜率计算

		IF Stop=TRUE THEN
               //判定斜率为正[数值增加]
               IF K > 0 AND TempVar[5] < TempVar[3] THEN
	                TempVar[5]:= TempVar[5] + AddValue;
               ELSIF K > 0 AND TempVar[5] > TempVar[3] THEN
	                TempVar[5]:= TempVar[3];
               END_IF

              //判定判定斜率为负[数值减小]
              IF K < 0 AND TempVar[5] > TempVar[3] THEN
	                 TempVar[5]:= TempVar[5] - AddValue;
              ELSIF K < 0 AND TempVar[5] < TempVar[3] THEN
	                 TempVar[5]:= TempVar[3];
              END_IF
	    END_IF

ELSIF Enable=FALSE THEN

	TempVar[5]:=0.0;

END_IF

RampOut:=TempVar[5];//Ramp输出

